import * as model from "../../../src/hop/model.ts";
import * as runs from "../../../src/hop/tests/runs.ts";
import * as world from "../../../src/hop/world.ts";
import type { World } from "../../../src/machine.ts";
import * as rt from "../../../src/runtime/index.ts";
import * as check from "../../support/checks.ts";

/** test the_meadow_can_be_won (hop/tests/runs.slg:42): the meadow is winnable, with every gem, without losing a life */
export function theMeadowCanBeWon(w: World): null {
  world.start(w, 1n);
  for (const h of runs.meadowWin()) {
    for (const i of rt.range(1n, h.ticks, true).list()) {
      world.step(w, runs.padOf(h.keys));
    }
  }
  check.assert(rt.equal(w.mode, model.Mode.make("Won")));
  check.assert(w.ticks === 316n);
  check.assert(w.taken.size === 3n);
  check.assert(w.lives === 3n);
  return null;
}

/** test the_ridge_can_be_won (hop/tests/runs.slg:54): the ridge is winnable too */
export function theRidgeCanBeWon(w: World): null {
  world.start(w, 2n);
  for (const h of runs.ridgeWin()) {
    for (const i of rt.range(1n, h.ticks, true).list()) {
      if (rt.equal(w.mode, model.Mode.make("Playing"))) {
        world.step(w, runs.padOf(h.keys));
      }
    }
  }
  check.assert(rt.equal(w.mode, model.Mode.make("Won")));
  check.assert(w.ticks === 549n);
  check.assert(w.taken.size === 3n);
  check.assert(w.lives === 3n);
  return null;
}
